def choose_move(observation):
    width = observation['grid_width']
    height = observation['grid_height']
    px, py = observation['self_position']
    enemy_x, enemy_y = observation['opponent_position']
    resources = observation['resources']
    obstacles = set(observation['obstacles'])
    remaining = observation['remaining_resource_count']

    def dist(x, y):
        return abs(px - x) + abs(py - y)

    # Find closest resource
    res = min(resources, key=lambda r: dist(r[0], r[1]), default=None)
    # Decide target
    if res:
        dx, dy = res[0] - px, res[1] - py
    else:
        dx, dy = 0, 0

    # Basic movement intent
    move_x = 0 if dx == 0 else (1 if dx > 0 else -1)
    move_y = 0 if dy == 0 else (1 if dy > 0 else -1)

    # Avoid obstacles
    def can_move(nx, ny):
        if (nx, ny) in obstacles:
            return False
        if nx < 0 or nx >= width or ny < 0 or ny >= height:
            return False
        return True

    if can_move(px + move_x, py + move_y):
        return [move_x, move_y]
    # Try alternative directions
    for dx_alt, dy_alt in [[0,1],[0,-1],[1,0],[-1,0]]:
        if can_move(px + dx_alt, py + dy_alt):
            return [dx_alt, dy_alt]
    return [0,0]
